2	// nothing here writes to a repo.
3	//
4	// ACCESS CONTROL IS THE VIEWER'S CREDENTIAL and there is nothing else — no backend,
5	// no shared token, no service account. Whichever provider `auth.mjs` used, the page
6	// calls api.github.com as that person, so a repo they cannot read stays unreadable
7	// and this page grants no access anyone did not already have.
8	//
9	// Caching is not an optimisation here, it is what makes a fleet view viable: see
10	// `cache.mjs` for why the three strategies differ. The rate-limit accounting below
11	// distinguishes calls that SPENT budget from 304s that did not, because "how much
12	// did that cost" is the question a viewer asks when a fleet sweep feels slow.
13	
14	import { immutable, validated, ageing, rateState, projectIssue, projectPull, projectRun, DAY_MS } from './cache.mjs';
15	
16	const API = 'https://api.github.com';
17	
18	export const rate = {
19	  remaining: null, limit: null, reset: null,
20	  spent: 0, revalidated: 0, served: 0, withheld: 0,
21	  // Set when GitHub says the budget is gone. Every later call in the same load reads
22	  // it and skips the request: twelve members' worth of calls that can only fail is
23	  // twelve more chances to trip the SECONDARY limit, which is measured in requests
24	  // made rather than in budget left.
25	  exhaustedUntil: null,
26	};
27	
28	export const resetCounters = () => { rate.spent = 0; rate.revalidated = 0; rate.served = 0; rate.withheld = 0; };
