30	// The budget policy this page is reading under. `budget.mjs` decides it; everything
31	// here only obeys it. The default is the old unconditional behaviour, so a caller
32	// that never sets one behaves exactly as before.
33	export let policy = { mode: 'live', minAge: 0, historyTtl: DAY_MS, spendCeiling: Infinity };
34	export const setPolicy = (p) => { policy = { ...policy, ...p }; };
35	
36	// Refusing to spend is not an error in the data — it is this page choosing to keep
