58	  rate.limit = s.limit ?? null;
59	  rate.reset = s.reset ?? null;
60	  rate.exhaustedUntil = s.exhaustedUntil ?? null;
61	  return s;
62	}
63	
64	export class GitHubError extends Error {
65	  constructor(status, path, detail) {
66	    super(`GitHub ${status} on ${path}${detail ? ` — ${detail}` : ''}`);
