84	  const r = headerNumber(res, 'x-ratelimit-remaining');
85	  if (r !== null) rate.remaining = r;
86	  const l = headerNumber(res, 'x-ratelimit-limit');
87	  if (l !== null) rate.limit = l;
88	  const t = headerNumber(res, 'x-ratelimit-reset');
89	  if (t !== null) rate.reset = t;
