1	// The fleet overview: every member at once, worst first, with a way into any one of
2	// them. `fleet.mjs` decides what the rows MEAN; this file fetches and draws them.
3	
4	import * as gh from './github.mjs';
5	import {
6	  summariseMember, rankMembers, rollUp, packSpread, taskSpread,
7	} from './fleet.mjs';
8	import { activitySeries } from './activity.mjs';
9	import {
10	  $, el, ago, duration, head, emptyRow, repoLink, tiles, segmentBar,
11	  reasonNodes, stackedColumns, chartLegend,
12	  LEVEL_GLYPH, STATE_ORDER, STATE_COLOR, STATE_UI, OUTCOME_COLOR,
13	} from './ui.mjs';
14	import { OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE } from '../../engine/scheduler/queue/work-item.mjs';
15	
16	// Members are read concurrently, but not all at once: a dozen members at six calls
17	// each is enough parallel load to trip secondary rate limiting, and the page is not
18	// in a hurry. Small and steady beats a burst that gets throttled.
19	const CONCURRENCY = 4;
20	
21	async function pool(items, worker, limit = CONCURRENCY) {
22	  const out = new Array(items.length);
23	  let next = 0;
24	  const runners = Array.from({ length: Math.min(limit, items.length) }, async () => {
25	    for (;;) {
26	      const i = next; next += 1;
27	      if (i >= items.length) return;
28	      out[i] = await worker(items[i], i);
29	    }
30	  });
31	  await Promise.all(runners);
32	  return out;
33	}
34	
35	// One member's raw reads. Everything is wrapped: a member that 404s, times out or is
36	// rate-limited becomes a row that SAYS SO, because one unreadable repo must not blank
37	// the other eleven.
38	async function readMember(repo, token, { withTree = true } = {}) {
39	  try {
40	    const meta = await gh.getRepo(repo, token);
41	    // The head commit, kept whole: its date is when this member last landed anything,
42	    // and it arrives in the call the content cache already makes for the sha.
43	    const head = await gh.getHead(repo, meta.default_branch, token);
44	    const sha = head.sha;
45	    const configText = await gh.getTextAtSha(repo, sha, '.claudinite-checks.json', token);
46	
47	    let declaration = null;
48	    if (configText) {
49	      try { declaration = JSON.parse(configText); } catch { declaration = null; }
50	    }
51	
52	    // A member that does not run Claudinite needs no further reads — and skipping
53	    // them is most of the saving on a fleet where not everything is adopted.
54	    if (!declaration) return { repo, declaration: null, defaultBranch: meta.default_branch, head };
55	
56	    const [tree, issuePage, runs] = await Promise.all([
57	      withTree ? gh.listTreeAtSha(repo, sha, token).catch(() => null) : Promise.resolve(null),
58	      // One page is the whole live queue plus recent history, which is all a fleet row
59	      // needs. Deep history is the per-repo view's job.
60	      gh.listIssues(repo, token, { pages: 1 }).catch(() => ({ issues: [] })),
61	      gh.listRuns(repo, token, 30).catch(() => []),
62	    ]);
63	
64	    return {
65	      repo,
66	      declaration,
67	      defaultBranch: meta.default_branch,
68	      sha,
69	      head,
70	      paths: tree?.paths ?? null,
71	      items: issuePage.issues,
72	      // Whether that page reached the end of this member's history. The activity
73	      // series needs it to tell a quiet day from a day it simply could not see.
74	      itemsComplete: issuePage.complete,
75	      prs: issuePage.prs ?? [],
76	      runs,
77	    };
78	  } catch (error) {
79	    return { repo, error };
80	  }
81	}
82	
83	// The canon reference the mount column compares against. Optional by design: with no
84	// `canonRepo` configured the column reads `unknown` rather than inventing `current`,
85	// and no repo name is ever hardcoded in engine code.
86	async function readCanon(config, token) {
87	  if (!config?.canonRepo) return null;
88	  try {
89	    const meta = await gh.getRepo(config.canonRepo, token);
90	    const ref = await gh.getHeadSha(config.canonRepo, meta.default_branch, token);
91	    const text = await gh.getTextAtSha(config.canonRepo, ref, '.claudinite-checks.json', token);
92	    let engineVersion = null;
93	    try { engineVersion = JSON.parse(text ?? '{}')?.claudinite?.engineVersion ?? null; } catch { /* absent */ }
94	    return { repo: config.canonRepo, ref, engineVersion };
95	  } catch {
96	    return null;
97	  }
98	}
99	
100	// --- render ---------------------------------------------------------------------
101	
102	const MOUNT_UI = {
103	  current: { label: 'current', cls: 'ok' },
104	  behind: { label: 'behind', cls: 'info' },
105	  'behind-engine': { label: 'old engine', cls: 'serious' },
106	  stalled: { label: 'stalled', cls: 'warning' },
107	  none: { label: 'no stamp', cls: 'warning' },
108	  unknown: { label: '—', cls: 'idle' },
109	};
110	
111	function memberRow(s, onOpen, now) {
112	  const open = (e) => { e.preventDefault(); onOpen(s.repo); };
113	
114	  const name = el('td', {}, [
115	    el('a', { href: `?repo=${encodeURIComponent(s.repo)}`, className: 'name', textContent: s.repo.split('/')[1] ?? s.repo, onclick: open }),
116	    el('div', { className: 'sub' }, [repoLink(s.repo)]),
117	  ]);
118	
119	  if (s.status !== 'adopted') {
120	    return el('tr', { className: `lvl-${s.level} muted-row` }, [
121	      name,
122	      el('td', { colSpan: 5 }, reasonNodes(s.reasons)),
123	      el('td', { className: 'nw' }, [el('a', { href: `?repo=${encodeURIComponent(s.repo)}`, textContent: 'open', onclick: open })]),
124	    ]);
125	  }
126	
127	  // Health: the worst reason, spelled out. Never a bare colour.
128	  const health = el('td', {}, s.reasons.length
129	    ? reasonNodes(s.reasons)
130	    : [el('span', { className: 'warn ok', textContent: `${LEVEL_GLYPH.ok} healthy` })]);
131	
132	  // Queue: the state mix as one thin bar plus the counts that are non-zero, so a
133	  // member with nothing open reads as empty rather than as a row of zeros.
134	  const counts = STATE_ORDER.filter((st) => s.open.byState[st] > 0)
135	    .map((st) => `${s.open.byState[st]} ${STATE_UI[st].label}`);
136	  const queue = el('td', {}, [
137	    segmentBar(STATE_ORDER.map((st) => [STATE_UI[st].label, s.open.byState[st], STATE_COLOR[st]]), { width: 92 }),
138	    el('div', { className: 'sub', textContent: counts.length ? counts.join(' · ') : 'nothing open' }),
139	  ]);
140	
141	  const outcomeBar = segmentBar([
142	    ['done', s.outcomes[OUTCOME_DONE], OUTCOME_COLOR[OUTCOME_DONE]],
143	    ['delivered', s.outcomes[OUTCOME_DELIVERED], OUTCOME_COLOR[OUTCOME_DELIVERED]],
144	    ['obsolete', s.outcomes[OUTCOME_OBSOLETE], OUTCOME_COLOR[OUTCOME_OBSOLETE]],
145	    ['no outcome', s.outcomes.none, OUTCOME_COLOR.none],
146	  ], { width: 92 });
147	
148	  const activity = el('td', {}, [
149	    outcomeBar,
150	    el('div', { className: 'sub', textContent: s.lastActivity ? ago(s.lastActivity, now) : (s.closedSeen ? 'unknown' : 'nothing closed yet') }),
151	  ]);
152	
153	  const runs = el('td', { className: 'nw' }, [
154	    el('div', {
155	      className: s.runs.consecutiveFailures ? 'warn critical' : 'sub',
156	      textContent: s.runs.consecutiveFailures
157	        ? `${LEVEL_GLYPH.critical} ${s.runs.consecutiveFailures} failing`
158	        : (s.runs.everRan ? 'passing' : 'never run'),
159	    }),
160	    el('div', { className: 'sub', textContent: s.runs.lastAt ? ago(s.runs.lastAt, now) : '—' }),
161	  ]);
162	
163	  const m = MOUNT_UI[s.mount.state] ?? MOUNT_UI.unknown;
164	  const mount = el('td', { className: 'nw' }, [
165	    el('div', { className: `warn ${m.cls}`, textContent: m.label }),
166	    el('div', { className: 'sub num', textContent: s.mount.ref ? s.mount.ref.slice(0, 7) : '—' }),
167	  ]);
168	
169	  const tasks = el('td', { className: 'num nw' }, [
170	    el('div', { textContent: s.declaredTasks == null ? '—' : String(s.declaredTasks) }),
171	    el('div', { className: 'sub', textContent: `${s.packs.length} packs` }),
172	  ]);
173	
174	  return el('tr', { className: `lvl-${s.level}` }, [name, health, queue, activity, runs, mount, tasks]);
175	}
