// Drive the dashboard in a real browser against a fake GitHub, and screenshot it.
//
//   node drive.mjs [--url http://[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]:8099/packs/claudinite-dashboard/] [--out shot.png]
//                  [--repo owner/name] [--wait 3000]
//
// The page is left untouched: `fetch` is stubbed in the page context before any module
// runs, so what renders is the real client against a synthetic fleet.

import { chromium } from '/opt/node22/lib/node_modules/playwright/index.mjs';

const arg = (name, fallback) => {
  const i = process.argv.indexOf(`--${name}`);
  return i === -1 ? fallback : process.argv[i + 1];
};

const url = arg('url', 'http://[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]:8099/packs/claudinite-dashboard/');
const out = arg('out', '/tmp/shot.png');
const wait = Number(arg('wait', 3500));

const browser = await chromium.launch({ executablePath: '/opt/pw-browsers/chromium/chrome-linux/chrome' });
const page = await browser.newPage({ viewport: { width: 1280, height: 1400 } });

page.on('console', (m) => process.stdout.write(`[console.${m.type()}] ${m.text()}\n`));
page.on('pageerror', (e) => process.stdout.write(`[pageerror] ${e.message}\n`));

await page.addInitScript(() => {
  const DAY = 86400e3;
  const now = Date.now();
  const iso = (d) => new Date(now - d * DAY).toISOString();
  const day = (d) => new Date(now - d * DAY).toISOString().slice(0, 10);

  const members = ['acme/alpha', 'acme/bravo', 'acme/charlie', 'acme/delta', 'acme/echo'];

  const item = (n, repo, task, over = {}) => ({
    number: n,
    title: `[claudinite-work] ${task}`,
    body: 'packs/basics/tasks/x/task.md\n',
    state: 'closed',
    labels: [{ name: 'outcome:done' }],
    created_at: iso(3),
    updated_at: iso(1),
    closed_at: iso(1),
    comments: 1,
    ...over,
  });

  const issuesFor = (repo) => {
    const i = members.indexOf(repo);
    const out = [];
    for (let d = 0; d < 12; d += 1) {
      const many = (i + d) % 3;
      for (let k = 0; k <= many; k += 1) {
        out.push(item(100 + d * 10 + k, repo, `core/task-${k}`, {
          closed_at: iso(d), updated_at: iso(d), created_at: iso(d + 1),
          labels: [{ name: ['outcome:done', 'outcome:delivered', 'outcome:obsolete'][(d + k) % 3] }],
        }));
      }
    }
    out.push(item(9, repo, 'core/parked', { state: 'open', labels: [{ name: 'needs-human' }], closed_at: null, updated_at: iso(4) }));
    if (i % 2) out.push(item(8, repo, 'core/ready', { state: 'open', labels: [{ name: 'ready' }], closed_at: null, updated_at: iso(0) }));
    out.push({ ...item(7, repo, 'x'), title: 'a plain issue', labels: [] });
    out.push({ ...item(6, repo, 'x'), title: 'a pull request', pull_request: { url: 'x' }, state: 'open', closed_at: null, draft: false, user: { login: 'someone' } });
    return out;
  };

  const runsFor = (repo) => {
    const i = members.indexOf(repo);
    const out = [];
    for (let d = 0; d < 10; d += 1) {
      out.push({
        name: 'Claudinite scheduler', status: 'completed',
        conclusion: (d === 2 && i === 1) ? 'failure' : 'success',
        event: 'schedule', head_branch: 'main', created_at: iso(d),
        html_url: 'https://example.invalid/run',
      });
    }
    return { workflow_runs: out };
  };

  const declaration = (repo) => JSON.stringify({
    packs: ['core', 'basics', 'tidy-repo', 'claudinite-dashboard'],
    taskScheduler: { dailyHour: 4 },
    claudinite: { ref: repo === 'acme/echo' ? 'oldsha0' : 'canonsha', engineVersion: 4, updated: iso(repo === 'acme/echo' ? 12 : 0) },
  });

  const digest = (d) => `Fleet operations — ${day(d)}\n\nYesterday's biggest work:\n\n`
    + `• alpha — #289 Ticket refresh now recovers from partial API failures. https://github.com/acme/alpha/pull/289\n\n`
    + `• bravo — #147 New release pipeline; version bumps are one command. https://github.com/acme/bravo/pull/147\n\n`
    + `Worth returning to:\n\n• acme/delta — last meaningful change ${day(21)}: #157 Store release automation. https://github.com/acme/delta/pull/157\n\n`
    + `Three weeks quiet. The store release landed but nothing has used it since — worth a look.\n`;

  const json = (body) => new Response(JSON.stringify(body), {
    status: 200,
    headers: { 'content-type': 'application/json', 'x-ratelimit-remaining': '4900', 'x-ratelimit-limit': '5000', 'x-ratelimit-reset': String(Math.floor(now / 1000) + 3000), etag: `W/"${Math.random()}"` },
  });
  const text = (body) => new Response(body, { status: 200, headers: { 'content-type': 'text/plain', 'x-ratelimit-remaining': '4900' } });
  const missing = () => new Response('Not Found', { status: 404, headers: { 'x-ratelimit-remaining': '4900' } });

  const real = window.fetch;
  window.fetch = async (input, init) => {
    const u = String(input);
    if (u.includes('dashboard.config.json')) {
      return json({ canonRepo: 'acme/alpha', repos: members, digestsRepo: 'acme/enforcer' });
    }
    if (!u.includes('api.github.com')) return real(input, init);

    const path = new URL(u).pathname;
    if (path === '/rate_limit') return json({ resources: { core: { remaining: 4900, limit: 5000, reset: Math.floor(now / 1000) + 3000 } } });
    if (path === '/user') return json({ login: 'viewer', avatar_url: '', html_url: '' });

    const m = /^\/repos\/([^/]+\/[^/]+)(\/.*)?$/.exec(path);
    if (!m) return missing();
    const [, repo, rest = ''] = m;
    if (repo === 'acme/charlie' && rest.startsWith('/contents')) return missing();   // not adopted
    if (rest === '') return json({ default_branch: 'main', private: false, full_name: repo });
    if (rest.startsWith('/commits/')) return json({ sha: `sha${repo.length}`, commit: { committer: { date: iso(members.indexOf(repo) % 4) } } });
    if (rest.startsWith('/contents/digests/')) {
      const d = decodeURIComponent(rest).match(/(\d{4}-\d{2}-\d{2})/)?.[1];
      return d === day(2) ? missing() : text(digest(1));
    }
    if (rest.startsWith('/contents/')) return text(declaration(repo));
    if (rest.startsWith('/git/trees/')) {
      return json({ tree: ['core', 'basics'].flatMap((p) => [1, 2].map((n) => ({ type: 'blob', path: `packs/${p}/tasks/task-${n}/task.mjs` }))) });
    }
    if (rest.startsWith('/issues')) return json(issuesFor(repo));
    if (rest.startsWith('/actions/runs')) return json(runsFor(repo));
    return missing();
  };
});

const target = arg('repo') ? `${url}?repo=${encodeURIComponent(arg('repo'))}` : url;
await page.goto(target, { waitUntil: 'load' });
await page.waitForTimeout(wait);
await page.screenshot({ path: out, fullPage: true });
process.stdout.write(`shot → ${out}\n`);
await browser.close();

